def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    pts=[(r,c) for r in range(h) for c in range(w) if g[r][c]==1]
    # Markers define full horizontal/vertical lines; recolor 2 objects hit by these rays.
    rows={r for r,c in pts if sum(1 for rr,cc in pts if rr==r)>=2}
    cols={c for r,c in pts if sum(1 for rr,cc in pts if cc==c)>=2}
    # In demo, aligned marker pairs at row 8, col 7. Color all zero cells on those lines,
    # and color complete 2-components intersecting either line, preserving untouched objects.
    hit=set()
    for r in range(h):
        for c in range(w):
            if g[r][c]==2 and (r in rows or c in cols): hit.add((r,c))
    # connected objects touched by marker lines
    seen=set()
    for r,c in [(r,c) for r,c in hit]:
        if (r,c) in seen: continue
        stack=[(r,c)]; comp=[]; seen.add((r,c))
        while stack:
            x,y=stack.pop(); comp.append((x,y))
            for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                q=(x+dx,y+dy)
                if 0<=q[0]<h and 0<=q[1]<w and g[q[0]][q[1]]==2 and q not in seen:
                    seen.add(q);stack.append(q)
        for x,y in comp:g[x][y]=1
    for r in rows:
        for c in range(w):
            if g[r][c]==0:g[r][c]=1
    for c in cols:
        for r in range(h):
            if g[r][c]==0:g[r][c]=1
    return g
