    byrow={}; bycol={}
    for r,c in markers: byrow.setdefault(r,[]).append(c); bycol.setdefault(c,[]).append(r)
    rays=[]
    for r,cs in byrow.items():
        if len(cs)>=2:rays.append(('h',r))
    for c,rs in bycol.items():
        if len(rs)>=2:rays.append(('v',c))
    # additionally markers at ends of a line indicate the full span is painted
    for typ,k in rays:
        if typ=='h':
            for c in range(w):
                if g[k][c]!=2:g[k][c]=1
        else:
            for r in range(h):
                if g[r][k]!=2:g[r][k]=1
    # Convert any 2-object touched by a ray; rays extend across objects completely.
    for typ,k in rays:
